import { money } from './menuHelpers'
import type { Category, Restaurant } from './menuHelpers'

export function Hero(p: { restaurant: Restaurant | null; table: string | null; closed: boolean }) {
  const r = p.restaurant
    const base = r?.primary_color || '#ea580c'
      return (
          <div>
                <div
                        style={{
                        background: `radial-gradient(circle at 85% 15%, rgba(255,255,255,0.2), transparent 45%), linear-gradient(160deg, ${base}, color-mix(in srgb, ${base} 55%, #1c0f08))`,
                        color: '#fff',
                                                      padding: '28px 20px 34px',
                                                                borderRadius: '0 0 28px 28px',
                                                                          textAlign: 'center',
                                                                                  }}
                                                                                        >
                                                                                                {r?.logo_url && (
                                                                                                          <img
                                                                                                                      src={r.logo_url}
                                                                                                                                  alt=""
                                                                                                                                              style={{
                                                                                                                                                            width: 72,
                                                                                                                                                                          height: 72,
                                                                                                                                                                                        borderRadius: '50%',
                                                                                                                                                                                                      objectFit: 'cover',
                                                                                                                                                                                                                    border: '3px solid rgba(255,255,255,0.8)',
                                                                                                                                                                                                                                }}
                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                          <h1 style={{ margin: '10px 0 0', fontSize: 30, fontWeight: 800 }}>{r?.name}</h1>
                                                                                                                                                                                                                                                                  {r?.slogan && <p style={{ margin: '4px 0 0', fontSize: 16, opacity: 0.95 }}>{r.slogan}</p>}
                                                                                                                                                                                                                                                                          <div style={{ marginTop: 10, display: 'flex', gap: 8, justifyContent: 'center', flexWrap: 'wrap' }}>
                                                                                                                                                                                                                                                                                    {r?.city && (
                                                                                                                                                                                                                                                                                                <span style={{ background: 'rgba(0,0,0,0.22)', padding: '4px 12px', borderRadius: 20, fontSize: 14 }}>
                                                                                                                                                                                                                                                                                                              📍 {r.city}
                                                                                                                                                                                                                                                                                                                          </span>
                                                                                                                                                                                                                                                                                                                                    )}
                                                                                                                                                                                                                                                                                                                                              {p.table && (
                                                                                                                                                                                                                                                                                                                                                          <span style={{ background: 'rgba(0,0,0,0.22)', padding: '4px 12px', borderRadius: 20, fontSize: 14 }}>
                                                                                                                                                                                                                                                                                                                                                                        🪑 Table {p.table}
                                                                                                                                                                                                                                                                                                                                                                                    </span>
                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                  {p.closed && (
                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ background: '#fee2e2', color: '#991b1b', padding: 12, textAlign: 'center', fontWeight: 600 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                    Restaurant is currently closed.
                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                        )
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                        interface TabsProps {
                                                                                                                                                                                                                                                                                                                                                                                                                                                          categories: Category[]
                                                                                                                                                                                                                                                                                                                                                                                                                                                            active: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                              onSelect: (id: string) => void
                                                                                                                                                                                                                                                                                                                                                                                                                                                                search: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onSearch: (v: string) => void
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    accent: string
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export function SearchAndTabs(p: TabsProps) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const chip = (id: string, text: string) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const on = p.active === id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            key={id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onClick={() => p.onSelect(id)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      padding: '9px 16px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderRadius: 24,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border: `2px solid ${on ? p.accent : '#eadfd3'}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: on ? p.accent : '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              color: on ? '#fff' : '#4a3a30',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fontSize: 15,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fontWeight: 700,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            whiteSpace: 'nowrap',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cursor: 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {text}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ position: 'sticky', top: 0, zIndex: 20, background: '#fbf6ef', padding: '12px 16px 8px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            value={p.search}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onChange={(e) => p.onSearch(e.target.value)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            placeholder="🔍  Search for a dish..."
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              width: '100%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        padding: '12px 16px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fontSize: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            borderRadius: 14,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      border: '1.5px solid #eadfd3',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          outline: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ display: 'flex', gap: 8, overflowX: 'auto', marginTop: 10, paddingBottom: 4 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {chip('all', 'All')}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {p.categories.map((c) => chip(c.id, c.name))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export function CartBar(p: { count: number; subtotal: number; accent: string; disabled: boolean; onOpen: () => void }) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (p.count === 0) return null
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                position: 'fixed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        left: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                right: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        bottom: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                padding: '10px 16px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        paddingBottom: 'calc(10px + env(safe-area-inset-bottom, 0px))',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                background: 'linear-gradient(to top, #fbf6ef 60%, rgba(251,246,239,0))',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        zIndex: 30,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onClick={p.onOpen}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        disabled={p.disabled}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                style={{
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          display: 'flex',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    width: '100%',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              maxWidth: 520,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        margin: '0 auto',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  alignItems: 'center',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            justifyContent: 'space-between',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      padding: '15px 20px',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                borderRadius: 16,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          border: 'none',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    background: p.disabled ? '#b9b0a8' : p.accent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              color: '#fff',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fontSize: 18,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  fontWeight: 800,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            boxShadow: '0 6px 18px rgba(0,0,0,0.25)',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cursor: p.disabled ? 'not-allowed' : 'pointer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    >
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span>🛒 {p.count} item{p.count > 1 ? 's' : ''}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <span>View cart · {money(p.subtotal)}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                